 el.dataset.type=o.type;el.dataset.color=o.color;el.dataset.shape=o.shape||'rectangle';el.dataset.locked=String(B.isLocked(scene,o));el.style.left=o.x+'px';el.style.top=o.y+'px';el.style.width=o.width+'px';el.style.height=o.height+'px';
