 updateEdges(scene=this.data){const nodes=new Map(scene.objects.map(o=>[o.id,o]));const sig=json(scene.connections.map(e=>[e,nodes.get(e.from)?.text,nodes.get(e.to)?.text]));if(this.edgeSignature===sig&&this.edgeEls){for(const e of scene.connections){const el=this.edgeEls.get(e.id),a=nodes.get(e.from),b=nodes.get(e.to);if(el&&a&&b){const g=B.connectorGeometry(a,b,e.style);el.querySelectorAll('path').forEach(p=>p.setAttribute('d',g.path));const label=el.querySelector('text');if(label){label.setAttribute('x',g.x);label.setAttribute('y',g.y-12)}}}return;}this.edgeSignature=sig;this.svg.innerHTML=`<defs><marker id="${this.uid}-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1 9 5 1 9" fill="none" stroke="context-stroke" stroke-width="1.5"/></marker></defs>`+scene.connections.map(e=>{const a=nodes.get(e.from),b=nodes.get(e.to);if(!a||!b)return'';const g=B.connectorGeometry(a,b,e.style);return`<g data-connection="${e.id}" tabindex="0" role="button" aria-label="${esc((a.text||labels[a.type])+' → '+(b.text||labels[b.type])+'. '+e.label)}" class="wb-connection ${this.selection.includes(e.id)?'is-selected':''}"><path class="wb-edge-hit" d="${g.path}"/><path class="wb-edge-line" d="${g.path}" ${e.arrow?`marker-end="url(#${this.uid}-arrow)"`:''}/>${e.label?`<text x="${g.x}" y="${g.y-12}" text-anchor="middle">${esc(e.label)}</text>`:''}</g>`}).join('');this.edgeEls=new Map([...this.svg.querySelectorAll('[data-connection]')].map(e=>[e.dataset.connection,e]));}
